# Binary Search in Rust

Here's a clean, idiomatic implementation using `i64` and a sorted slice:

```rust
/// Performs a binary search over a sorted slice of `i64`.
///
/// Returns `Some(index)` if the value is found, `None` otherwise.
///
/// # Examples
///
/// ```
/// use binary_search::binary_search;
///
/// let v = [1, 3, 5, 7, 9];
/// assert_eq!(binary_search(&v, 5), Some(2));
/// assert_eq!(binary_search(&v, 4), None);
/// ```
pub fn binary_search(haystack: &[i64], needle: i64) -> Option<usize> {
    let mut low = 0usize;
    let mut high = haystack.len();

    while low < high {
        let mid = low + (high - low) / 2;
        match haystack[mid].cmp(&needle) {
            std::cmp::Ordering::Less => low = mid + 1,
